import React, { useEffect, useState } from "react";
import axios from "../Axios"; // ✅ Import your configured Axios instance

const Comment = ({ postId, user }) => {
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState("");
  const token = localStorage.getItem("authToken");
  const [showAll, setShowAll] = useState(false);

  useEffect(() => {
    fetchComments();
  }, []);

  // ✅ Fetch comments using Axios
  const fetchComments = async () => {
    try {
      const response = await axios.get(`/api/comments/post/${postId}`);
      setComments(response.data);
    } catch (error) {
      console.error("Error fetching comments:", error.response?.data || error.message);
    }
  };

  // ✅ Add comment using Axios
  const addComment = async () => {
    if (!newComment) {
      console.error("Comment is empty.");
      return;
    }

    try {
      const response = await axios.post(`/api/comments/add`, 
        { postId, content: newComment },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setComments([...comments, response.data]);
      setNewComment("");
    } catch (error) {
      console.error("Failed to add comment:", error.response?.data || error.message);
    }
  };

  // ✅ Update comment using Axios
  const updateComment = async (commentId, newContent) => {
    if (!newContent) return;

    try {
      await axios.put(`/api/comments/update/${commentId}`, 
        { userId: user.id, newContent },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchComments();
    } catch (error) {
      console.error("Error updating comment:", error.response?.data || error.message);
    }
  };

  // ✅ Delete comment using Axios
  const deleteComment = async (commentId) => {
    try {
      await axios.delete(`/api/comments/delete/${commentId}`, {
        headers: { Authorization: `Bearer ${token}` },
        data: { userId: user.id }
      });

      setComments(comments.filter(comment => comment.id !== commentId));
    } catch (error) {
      console.error("Error deleting comment:", error.response?.data || error.message);
    }
  };

  return (
    <div>
      <h4>Comments</h4>
      {comments.slice(0, showAll ? comments.length : 5).map((comment) => (
        <div key={comment.id}>
          <p><strong>{comment.user.username}</strong>: {comment.content}</p>
          {comment.user.id === user.id && (
            <>
              <button onClick={() => updateComment(comment.id, prompt("Edit comment:", comment.content))}>Edit</button>
              <button onClick={() => deleteComment(comment.id)}>Delete</button>
            </>
          )}
        </div>
      ))}
      {comments.length > 5 && !showAll && (
        <button onClick={() => setShowAll(true)}>Show More</button>
      )}
      <input value={newComment} onChange={(e) => setNewComment(e.target.value)} placeholder="Write a comment..." />
      <button onClick={addComment}>Comment</button>
    </div>
  );
};

export default Comment;


